// IS-A: Inheritance (Specialization)
class Asset {
    virtual void sell() = 0;
};

class Stock : public Asset {
    // Stock IS-A specialized Asset
    void sell() override {}
};

// HAS-A: Composition (Containment)
class SteeringWheel {
    void turn() {}
};

class Vehicle {
    // Vehicle HAS-A SteeringWheel
    SteeringWheel wheel;
    void drive() { wheel.turn(); }
};
